);
CREATE TEMP TABLE lesson_invoices (
  invoice_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  student_id BIGINT NOT NULL REFERENCES pg_temp.lesson_students(student_id),
  period_month DATE NOT NULL,
  amount NUMERIC(12,2) NOT NULL CHECK (amount >= 0),
  UNIQUE (student_id, period_month)
);
